/**
 * Set job name with validation
 * @param value - Job name (max 240 chars, alphanumeric)
 */
public void setJobName(String value) {
    // Validate max length
    if (value != null && value.length() > 240) {
        throw MessageHelper.createError(
            MessageConstants.ERR_FIELD_TOO_LONG,
            new String[]{"Job Name", "240"}
        );
    }

    // Validate alphanumeric
    if (value != null && !value.matches("^[a-zA-Z0-9 ]+$")) {
        throw MessageHelper.createError(
            MessageConstants.ERR_INVALID_FORMAT,
            new String[]{"Job Name", "alphanumeric characters only"}
        );
    }

    setAttributeInternal(JOBNAME, value);
}

