 * Called from PositionEOImpl
 */
public void validateChildPosition(PositionEOImpl position) {
    Date jobStartDate = this.getStartDate();
    Date jobEndDate = this.getEndDate();
    Date posStartDate = position.getStartDate();
    Date posEndDate = position.getEndDate();

    // Position start must be within job date range
    if (posStartDate.compareTo(jobStartDate) < 0) {
        throw MessageHelper.createError(
            MessageConstants.ERR_POSITION_START_BEFORE_JOB,
            new String[]{position.getPositionName(), this.getJobName()}
        );
    }

    // Position end must be within job date range
    if (jobEndDate != null && 
        (posEndDate == null || posEndDate.compareTo(jobEndDate) > 0)) {
        throw MessageHelper.createError(
            MessageConstants.ERR_POSITION_END_AFTER_JOB,
            new String[]{position.getPositionName(), this.getJobName()}
        );
