/**
 * Check if job name was changed
 */
public boolean isJobNameChanged() {
    String currentName = getJobName();
    String postedName = (String)getPostedAttribute(JOBNAME);

    if (currentName == null && postedName == null) return false;
    if (currentName == null || postedName == null) return true;

    return !currentName.equals(postedName);
}

/**
 * Get original salary from database before modification
 */
public Number getOriginalSalary() {
    return (Number)getPostedAttribute(SALARY);
}

/**
 * Calculate salary change percentage
 */
public double getSalaryChangePercent() {
    Number current = getSalary();
    Number original = (Number)getPostedAttribute(SALARY);

    if (original == null || original.doubleValue() == 0) return 0;
    if (current == null) return -100;

    double diff = current.doubleValue() - original.doubleValue();
    return (diff / original.doubleValue()) * 100;
}

