/**
 * processFormRequest() - Called when user submits form or clicks button
 * Purpose: Handle user events, validate input, call AM methods
 * Timing: Called AFTER processRequest, handles POST requests
 */
public void processFormRequest(OAPageContext pageContext, OAWebBean webBean) {
    // Always call super first
    super.processFormRequest(pageContext, webBean);

    // Get Application Module
    OAApplicationModule am = pageContext.getApplicationModule(webBean);

    // Get event parameter (typically from button click)
    String event = pageContext.getParameter(EVENT_PARAM);

    // Example 1: Save button clicked
    if ("save".equals(event)) {
        // Get form field values
        String empName = pageContext.getParameter("EmpName");
        String email = pageContext.getParameter("Email");
        String salary = pageContext.getParameter("Salary");

        // Validate required fields
        if (empName == null || empName.trim().length() == 0) {
            throw MessageHelper.createFieldRequiredError("Employee Name");
        }

        if (email == null || email.trim().length() == 0) {
            throw MessageHelper.createFieldRequiredError("Email");
        }

        // Call AM method to save
        am.invokeMethod("saveEmployee", new Object[]{
            empName,
            email,
            salary == null ? null : new Number(salary)
        });

        // Navigate back to search page
        pageContext.forwardImmediately(
            "OA.jsp?page=/oracle/apps/xx/emp/webui/EmpSearchPG",
            null,
            OAWebBeanConstants.KEEP_MENU_CONTEXT,
            null,
            null,
            true,
