    // Example 3: Search button clicked
    else if ("search".equals(event)) {
        String searchName = pageContext.getParameter("SearchName");
        String searchDept = pageContext.getParameter("SearchDept");

        am.invokeMethod("searchEmployees", new Object[]{
            searchName,
            searchDept == null ? null : new Number(searchDept)
        });

        // Stay on same page (no navigation)
    }

    // Example 4: Cancel button clicked
    else if ("cancel".equals(event)) {
        // Rollback changes
        am.invokeMethod("rollback");

        // Navigate back
        pageContext.forwardImmediately(
            "OA.jsp?page=/oracle/apps/xx/emp/webui/EmpSearchPG",
            null,
            OAWebBeanConstants.KEEP_MENU_CONTEXT,
            null,
            null,
            true,
            OAWebBeanConstants.ADD_BREAD_CRUMB_NO
        );
    }
}

