/**
 * processFormRequest() - Advanced event handling
 */
public void processFormRequest(OAPageContext pageContext, OAWebBean webBean) {
    super.processFormRequest(pageContext, webBean);

    OAApplicationModule am = pageContext.getApplicationModule(webBean);
    String event = pageContext.getParameter(EVENT_PARAM);

    // Pattern 1: Delete with confirmation dialog
    if ("delete".equals(event)) {
        String empId = pageContext.getParameter("EmpId");

        // Check if user already confirmed
        String dialogResponse = pageContext.getParameter("DeleteConfirm");

        if ("yes".equals(dialogResponse)) {
            // User confirmed - perform delete
            am.invokeMethod("deleteEmployee", new Object[]{new Number(empId)});

            // Show success message and navigate
            throw MessageHelper.createDeleteSuccessMessage();
        } else {
            // Show confirmation dialog
            MessageHelper.showConfirmation(
                pageContext,
                "Are you sure you want to delete this employee?",
                "DeleteConfirm"
            );
            return; // Stop processing
        }
    }

    // Pattern 2: Multi-step wizard (step tracking)
    else if ("next".equals(event)) {
        String currentStep = pageContext.getParameter("WizardStep");
        int step = currentStep == null ? 1 : Integer.parseInt(currentStep);

        if (step == 1) {
            // Validate step 1 data
            validateStep1(pageContext);

            // Save step 1 data to AM
            am.invokeMethod("saveStep1Data", getStep1Parameters(pageContext));

            // Navigate to step 2
            HashMap params = new HashMap();
            params.put("WizardStep", "2");
            pageContext.setForwardURL(
                "OA.jsp?page=/oracle/apps/xx/emp/webui/EmpWizardStep2PG",
                null,
                OAWebBeanConstants.KEEP_MENU_CONTEXT,
                null,
                params,
                true,
                OAWebBeanConstants.ADD_BREAD_CRUMB_YES,
                OAWebBeanConstants.IGNORE_MESSAGES
            );
        } else if (step == 2) {
            validateStep2(pageContext);
            am.invokeMethod("saveStep2Data", getStep2Parameters(pageContext));

            // Navigate to step 3
            HashMap params = new HashMap();
            params.put("WizardStep", "3");
            pageContext.setForwardURL(
                "OA.jsp?page=/oracle/apps/xx/emp/webui/EmpWizardStep3PG",
                null,
                OAWebBeanConstants.KEEP_MENU_CONTEXT,
                null,
                params,
                true,
                OAWebBeanConstants.ADD_BREAD_CRUMB_YES,
                OAWebBeanConstants.IGNORE_MESSAGES
            );
        }
    }

    // Pattern 3: Add/Remove rows in table
    else if ("addRow".equals(event)) {
        am.invokeMethod("addNewPosition");
        // Stay on same page - table will refresh
    }
    else if ("deleteRow".equals(event)) {
        String rowRef = pageContext.getParameter("DeleteRowRef");
        am.invokeMethod("deletePositionRow", new Object[]{rowRef});
    }

    // Pattern 4: Download file
    else if ("download".equals(event)) {
        String reportId = pageContext.getParameter("ReportId");

        // Generate file
        byte[] fileContent = (byte[])am.invokeMethod(
            "generateReport", 
            new Object[]{new Number(reportId)}
        );

        // Set response headers for download
        HttpServletResponse response = 
            (HttpServletResponse)pageContext.getRenderingContext()
                                           .getServletResponse();

        response.setContentType("application/vnd.ms-excel");
        response.setHeader("Content-Disposition", 
                          "attachment; filename=Employee_Report.xls");

        try {
            ServletOutputStream os = response.getOutputStream();
            os.write(fileContent);
            os.flush();
            os.close();
        } catch (IOException e) {
            throw new OAException("Error downloading file: " + e.getMessage());
        }
    }

    // Pattern 5: Batch operations on selected rows
    else if ("approveSelected".equals(event)) {
        String[] selectedRows = pageContext.getParameterValues("SelectRow");

        if (selectedRows == null || selectedRows.length == 0) {
            throw MessageHelper.createError(
                MessageConstants.ERR_NO_ROWS_SELECTED,
                null
            );
        }

        // Process each selected row
        for (String empId : selectedRows) {
            am.invokeMethod("approveEmployee", new Object[]{new Number(empId)});
        }

        throw MessageHelper.createSuccessMessage(
            selectedRows.length + " employee(s) approved successfully"
        );
    }
}

