/**
 * processFormData() - Handle file uploads
 * Purpose: Process multipart/form-data requests (file uploads)
 * Timing: Called BEFORE processRequest when form has enctype=multipart/form-data
 */
public void processFormData(OAPageContext pageContext, OAWebBean webBean) {
    // Always call super first
    super.processFormData(pageContext, webBean);

    // Get Application Module
    OAApplicationModule am = pageContext.getApplicationModule(webBean);

    // Example 1: Single file upload
    DataObject fileUpload = pageContext.getNamedDataObject("FileUpload");

    if (fileUpload != null) {
        // Get file properties
        String fileName = (String)fileUpload.selectValue(null, "UPLOAD_FILE_NAME");
        String mimeType = (String)fileUpload.selectValue(null, "UPLOAD_FILE_MIME_TYPE");
        BlobDomain fileContent = (BlobDomain)fileUpload.selectValue(null, fileUpload);

        // Validate file type
        if (!"application/pdf".equals(mimeType) && 
            !"application/vnd.ms-excel".equals(mimeType)) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_TYPE,
                new String[]{"PDF or Excel"}
            );
        }

        // Validate file size (e.g., max 5MB)
        long fileSize = fileContent.getLength();
        long maxSize = 5 * 1024 * 1024; // 5MB in bytes

        if (fileSize > maxSize) {
            throw MessageHelper.createError(
                MessageConstants.ERR_FILE_TOO_LARGE,
                new String[]{"5MB"}
            );
        }

        // Call AM method to save file
        am.invokeMethod("uploadEmployeeDocument", new Object[]{
            fileName,
            mimeType,
            fileContent
        });
    }
}

