/**
 * processFormData() - Advanced file upload handling
 */
public void processFormData(OAPageContext pageContext, OAWebBean webBean) {
    super.processFormData(pageContext, webBean);

    OAApplicationModule am = pageContext.getApplicationModule(webBean);

    // Pattern 1: Multiple file uploads
    Hashtable uploadedFiles = pageContext.getMultipartFormData();

    if (uploadedFiles != null && !uploadedFiles.isEmpty()) {
        Enumeration fileNames = uploadedFiles.keys();

        while (fileNames.hasMoreElements()) {
            String fieldName = (String)fileNames.nextElement();
            DataObject fileData = (DataObject)uploadedFiles.get(fieldName);

            if (fileData != null) {
                processUploadedFile(pageContext, am, fieldName, fileData);
            }
        }
    }

    // Pattern 2: Excel file import with validation
    DataObject excelFile = pageContext.getNamedDataObject("ExcelImport");

    if (excelFile != null) {
        String fileName = (String)excelFile.selectValue(null, "UPLOAD_FILE_NAME");
        BlobDomain content = (BlobDomain)excelFile.selectValue(null, excelFile);

        // Validate Excel file
        if (!fileName.endsWith(".xls") && !fileName.endsWith(".xlsx")) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_FORMAT,
                new String[]{"Excel (.xls or .xlsx)"}
            );
        }

        try {
            // Parse Excel and import data
            Integer recordCount = (Integer)am.invokeMethod(
                "importEmployeesFromExcel",
                new Object[]{fileName, content}
            );

            // Store success message in session
            pageContext.putSessionValue(
                "ImportSuccessMsg",
                recordCount + " employees imported successfully"
            );

        } catch (Exception e) {
            throw MessageHelper.createError(
                MessageConstants.ERR_FILE_IMPORT_FAILED,
                new String[]{e.getMessage()}
            );
        }
    }

    // Pattern 3: Image upload with thumbnail generation
    DataObject imageFile = pageContext.getNamedDataObject("EmployeePhoto");

    if (imageFile != null) {
        String fileName = (String)imageFile.selectValue(null, "UPLOAD_FILE_NAME");
        String mimeType = (String)imageFile.selectValue(null, "UPLOAD_FILE_MIME_TYPE");
        BlobDomain imageContent = (BlobDomain)imageFile.selectValue(null, imageFile);

        // Validate image type
        if (!mimeType.startsWith("image/")) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_TYPE,
                new String[]{"Image (JPEG, PNG, GIF)"}
            );
        }

        // Validate image size (max 2MB)
        if (imageContent.getLength() > 2 * 1024 * 1024) {
            throw MessageHelper.createError(
                MessageConstants.ERR_FILE_TOO_LARGE,
                new String[]{"2MB"}
            );
        }

        // Process image (resize, create thumbnail)
        am.invokeMethod("saveEmployeePhoto", new Object[]{
            pageContext.getParameter("EmpId"),
            fileName,
            imageContent
        });
    }
}

/**
 * Helper method to process individual uploaded file
 */
private void processUploadedFile(OAPageContext pageContext,
                                 OAApplicationModule am,
                                 String fieldName,
                                 DataObject fileData) {
    String fileName = (String)fileData.selectValue(null, "UPLOAD_FILE_NAME");
    String mimeType = (String)fileData.selectValue(null, "UPLOAD_FILE_MIME_TYPE");
    BlobDomain content = (BlobDomain)fileData.selectValue(null, fileData);

    // Validate and process based on field name
    if ("Resume".equals(fieldName)) {
        // Process resume upload
        am.invokeMethod("saveResume", new Object[]{fileName, content});
    } else if ("Certificate".equals(fieldName)) {
        // Process certificate upload
        am.invokeMethod("saveCertificate", new Object[]{fileName, content});
    }
}

