/**
 * processFormData() - PDF Upload with Validation
 */
public void processFormData(OAPageContext pageContext, OAWebBean webBean) {
    super.processFormData(pageContext, webBean);

    OAApplicationModule am = pageContext.getApplicationModule(webBean);
    DataObject pdfFile = pageContext.getNamedDataObject("PDFDocument");

    if (pdfFile != null) {
        String fileName = (String)pdfFile.selectValue(null, "UPLOAD_FILE_NAME");
        String mimeType = (String)pdfFile.selectValue(null, "UPLOAD_FILE_MIME_TYPE");
        BlobDomain content = (BlobDomain)pdfFile.selectValue(null, pdfFile);

        // Validate PDF MIME type
        if (!"application/pdf".equals(mimeType)) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_TYPE,
                new String[]{"PDF"}
            );
        }

        // Validate file extension
        if (!fileName.toLowerCase().endsWith(".pdf")) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_FORMAT,
                new String[]{"PDF (.pdf)"}
            );
        }

        // Validate file size (max 20MB for PDF)
        long fileSize = content.getLength();
        long maxSize = 20 * 1024 * 1024; // 20MB

        if (fileSize > maxSize) {
            throw MessageHelper.createError(
                MessageConstants.ERR_FILE_TOO_LARGE,
                new String[]{"20MB"}
            );
        }

        try {
            // Validate PDF content (check magic number)
            byte[] header = new byte[4];
            InputStream is = content.getInputStream();
            is.read(header);
            is.close();

            // PDF files start with %PDF
            String headerStr = new String(header);
            if (!headerStr.startsWith("%PDF")) {
                throw MessageHelper.createError(
                    MessageConstants.ERR_CORRUPTED_FILE,
                    new String[]{"Not a valid PDF file"}
                );
            }

            // Extract PDF metadata (optional)
            HashMap<String, Object> metadata = new HashMap<String, Object>();
            metadata.put("fileName", fileName);
            metadata.put("fileSize", fileSize);
            metadata.put("uploadDate", new Date(System.currentTimeMillis()));
            metadata.put("uploadedBy", pageContext.getUserId());

            // Get document type from form
            String docType = pageContext.getParameter("DocumentType");
            if (docType == null || docType.trim().isEmpty()) {
                throw MessageHelper.createFieldRequiredError("Document Type");
            }
            metadata.put("documentType", docType);

            // Save PDF with metadata
            am.invokeMethod("savePDFDocument", new Object[]{
                content,
                metadata
            });

            // Store success message
            pageContext.putSessionValue(
                "UploadSuccess",
                "PDF document uploaded successfully: " + fileName
            );

        } catch (IOException e) {
            throw new OAException("Error processing PDF file: " + e.getMessage());
        }
    }
}

