/**
 * processFormData() - ZIP File Upload and Extraction
 */
public void processFormData(OAPageContext pageContext, OAWebBean webBean) {
    super.processFormData(pageContext, webBean);

    OAApplicationModule am = pageContext.getApplicationModule(webBean);
    DataObject zipFile = pageContext.getNamedDataObject("ZipFile");

    if (zipFile != null) {
        String fileName = (String)zipFile.selectValue(null, "UPLOAD_FILE_NAME");
        BlobDomain content = (BlobDomain)zipFile.selectValue(null, zipFile);

        // Validate ZIP extension
        if (!fileName.toLowerCase().endsWith(".zip")) {
            throw MessageHelper.createError(
                MessageConstants.ERR_INVALID_FILE_FORMAT,
                new String[]{"ZIP"}
            );
        }

        // Validate file size (max 50MB for ZIP)
        if (content.getLength() > 50 * 1024 * 1024) {
            throw MessageHelper.createError(
                MessageConstants.ERR_FILE_TOO_LARGE,
                new String[]{"50MB"}
            );
        }

        try {
            // Extract ZIP contents
            InputStream is = content.getInputStream();
            ZipInputStream zis = new ZipInputStream(is);

            ArrayList<HashMap> extractedFiles = new ArrayList<HashMap>();
            ZipEntry entry;
            int fileCount = 0;
            int maxFiles = 100; // Limit number of files

            while ((entry = zis.getNextEntry()) != null && fileCount < maxFiles) {
                if (!entry.isDirectory()) {
                    String entryName = entry.getName();
                    long entrySize = entry.getSize();

                    // Validate individual file size
                    if (entrySize > 10 * 1024 * 1024) {
                        throw new OAException(
                            "File too large in ZIP: " + entryName + " (max 10MB per file)"
                        );
                    }

                    // Read file content
                    ByteArrayOutputStream baos = new ByteArrayOutputStream();
                    byte[] buffer = new byte[4096];
                    int bytesRead;

                    while ((bytesRead = zis.read(buffer)) != -1) {
                        baos.write(buffer, 0, bytesRead);
                    }

                    byte[] fileContent = baos.toByteArray();
                    baos.close();

                    // Determine MIME type from extension
                    String mimeType = getMimeTypeFromFileName(entryName);

                    // Validate file type (only allow specific types)
                    if (!isAllowedFileType(mimeType)) {
                        throw new OAException(
                            "File type not allowed: " + entryName
                        );
                    }

                    // Store file info
                    HashMap<String, Object> fileInfo = new HashMap<String, Object>();
                    fileInfo.put("fileName", entryName);
                    fileInfo.put("mimeType", mimeType);
                    fileInfo.put("content", fileContent);
                    fileInfo.put("size", fileContent.length);

                    extractedFiles.add(fileInfo);
                    fileCount++;
                }
                zis.closeEntry();
            }

            zis.close();

            if (fileCount >= maxFiles) {
                throw new OAException(
                    "ZIP contains too many files (max " + maxFiles + ")"
                );
            }

            // Process extracted files
            am.invokeMethod("processExtractedFiles", new Object[]{extractedFiles});

            // Store success message
            pageContext.putSessionValue(
                "ExtractionSuccess",
                fileCount + " files extracted from " + fileName
            );

        } catch (IOException e) {
            throw new OAException("Error extracting ZIP file: " + e.getMessage());
        }
    }
}

/**
 * Get MIME type from file name
 */
private String getMimeTypeFromFileName(String fileName) {
    String extension = fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase();

    if ("pdf".equals(extension)) return "application/pdf";
    if ("xls".equals(extension)) return "application/vnd.ms-excel";
    if ("xlsx".equals(extension)) return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    if ("doc".equals(extension)) return "application/msword";
    if ("docx".equals(extension)) return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
    if ("jpg".equals(extension) || "jpeg".equals(extension)) return "image/jpeg";
    if ("png".equals(extension)) return "image/png";
    if ("txt".equals(extension)) return "text/plain";

    return "application/octet-stream";
}

/**
 * Check if file type is allowed
 */
private boolean isAllowedFileType(String mimeType) {
    String[] allowedTypes = {
        "application/pdf",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "image/jpeg",
        "image/png",
        "text/plain"
    };

    for (String allowed : allowedTypes) {
        if (allowed.equals(mimeType)) {
            return true;
        }
    }
    return false;
}

