/**
 * processFormData() - Multiple Attachments Pattern
 */
public void processFormData(OAPageContext pageContext, OAWebBean webBean) {
    super.processFormData(pageContext, webBean);

    OAApplicationModule am = pageContext.getApplicationModule(webBean);

    // Get entity ID (e.g., Employee ID, Job ID)
    String entityId = pageContext.getParameter("EntityId");
    String entityType = pageContext.getParameter("EntityType");

    if (entityId == null || entityType == null) {
        throw MessageHelper.createError(
            MessageConstants.ERR_MISSING_PARAMETER,
            new String[]{"Entity ID and Type"}
        );
    }

    // Process multiple file uploads
    Hashtable uploadedFiles = pageContext.getMultipartFormData();

    if (uploadedFiles != null && !uploadedFiles.isEmpty()) {
        int successCount = 0;
        int errorCount = 0;
        StringBuilder errors = new StringBuilder();

        Enumeration fileFields = uploadedFiles.keys();

        while (fileFields.hasMoreElements()) {
            String fieldName = (String)fileFields.nextElement();
            DataObject fileData = (DataObject)uploadedFiles.get(fieldName);

            if (fileData != null) {
                try {
                    String fileName = (String)fileData.selectValue(null, "UPLOAD_FILE_NAME");
                    String mimeType = (String)fileData.selectValue(null, "UPLOAD_FILE_MIME_TYPE");
                    BlobDomain content = (BlobDomain)fileData.selectValue(null, fileData);

                    // Skip empty files
                    if (fileName == null || fileName.trim().isEmpty()) {
                        continue;
                    }

                    // Validate file size (max 15MB per file)
                    if (content.getLength() > 15 * 1024 * 1024) {
                        errorCount++;
                        errors.append(fileName).append(": File too large (max 15MB)\n");
                        continue;
                    }

                    // Determine attachment category from field name
                    String category = getAttachmentCategory(fieldName);

                    // Create attachment metadata
                    HashMap<String, Object> attachment = new HashMap<String, Object>();
                    attachment.put("entityId", new Number(entityId));
                    attachment.put("entityType", entityType);
                    attachment.put("fileName", fileName);
                    attachment.put("mimeType", mimeType);
                    attachment.put("fileContent", content);
                    attachment.put("fileSize", content.getLength());
                    attachment.put("category", category);
                    attachment.put("uploadDate", new Date(System.currentTimeMillis()));
                    attachment.put("uploadedBy", pageContext.getUserId());

                    // Save attachment via AM
                    am.invokeMethod("saveAttachment", new Object[]{attachment});
                    successCount++;

                } catch (Exception e) {
                    errorCount++;
                    errors.append(fieldName).append(": ").append(e.getMessage()).append("\n");
                }
            }
        }

        // Commit if any successful uploads
        if (successCount > 0) {
            getOADBTransaction().commit();
        }

        // Prepare result message
        String message = successCount + " file(s) uploaded successfully.";
        if (errorCount > 0) {
            message += " " + errorCount + " file(s) failed:\n" + errors.toString();
        }

        pageContext.putSessionValue("AttachmentResult", message);
    }
}

/**
 * Determine attachment category from field name
 */
private String getAttachmentCategory(String fieldName) {
    if (fieldName.contains("Resume")) return "RESUME";
    if (fieldName.contains("Certificate")) return "CERTIFICATE";
    if (fieldName.contains("Photo")) return "PHOTO";
    if (fieldName.contains("Contract")) return "CONTRACT";
    if (fieldName.contains("IdProof")) return "ID_PROOF";
    if (fieldName.contains("Other")) return "OTHER";
    return "GENERAL";
}

